UPDATE NodeStructuralBlueprints SET EventTypePaletteJson = '[{"BeatIndex":0,"EventType":"discovery","RevelationMode":"curiosity"},{"BeatIndex":1,"EventType":"arrival","RevelationMode":"none"},{"BeatIndex":2,"EventType":"negotiation","RevelationMode":"none"},{"BeatIndex":3,"EventType":"assembly","RevelationMode":"none"},{"BeatIndex":4,"EventType":"confession","RevelationMode":"curiosity"},{"BeatIndex":5,"EventType":"confrontation","RevelationMode":"none"},{"BeatIndex":6,"EventType":"discovery","RevelationMode":"none"},{"BeatIndex":7,"EventType":"discovery","RevelationMode":"none"},{"BeatIndex":8,"EventType":"vigil","RevelationMode":"none"},{"BeatIndex":9,"EventType":"negotiation","RevelationMode":"curiosity"},{"BeatIndex":10,"EventType":"absence","RevelationMode":"none"},{"BeatIndex":11,"EventType":"confrontation","RevelationMode":"none"},{"BeatIndex":12,"EventType":"display","RevelationMode":"none"},{"BeatIndex":13,"EventType":"negotiation","RevelationMode":"curiosity"},{"BeatIndex":14,"EventType":"confession","RevelationMode":"none"},{"BeatIndex":15,"EventType":"vigil","RevelationMode":"none"},{"BeatIndex":16,"EventType":"confrontation","RevelationMode":"curiosity"},{"BeatIndex":17,"EventType":"discovery","RevelationMode":"none"},{"BeatIndex":18,"EventType":"discovery","RevelationMode":"none"},{"BeatIndex":19,"EventType":"confrontation","RevelationMode":"curiosity"},{"BeatIndex":20,"EventType":"assembly","RevelationMode":"none"},{"BeatIndex":21,"EventType":"confrontation","RevelationMode":"none"},{"BeatIndex":22,"EventType":"confrontation","RevelationMode":"curiosity"},{"BeatIndex":23,"EventType":"vigil","RevelationMode":"none"},{"BeatIndex":24,"EventType":"exchange","RevelationMode":"none"},{"BeatIndex":25,"EventType":"decision","RevelationMode":"curiosity"},{"BeatIndex":26,"EventType":"confrontation","RevelationMode":"curiosity"},{"BeatIndex":27,"EventType":"repair","RevelationMode":"none"},{"BeatIndex":28,"EventType":"vigil","RevelationMode":"none"},{"BeatIndex":29,"EventType":"departure","RevelationMode":"none"}]',
UpdatedAt = SYSUTCDATETIME()
WHERE NodeId = (SELECT Id FROM Nodes WHERE NodeCode='BLST');
SELECT CASE WHEN EventTypePaletteJson LIKE '%surprise%' OR EventTypePaletteJson LIKE '%suspense%' OR EventTypePaletteJson LIKE '%"revelation"%' THEN 'STILL DIRTY' ELSE 'CLEAN' END AS PaletteState
FROM NodeStructuralBlueprints WHERE NodeId = (SELECT Id FROM Nodes WHERE NodeCode='BLST');
